/**
 * The features the CLI can generate: one entry per directory under
 * apps/<framework>/src/oidc-provider/features/ (apps/hono) and
 * src/app/_oidc-provider/features/ (apps/nextjs).
 *
 * The entry says what --enable / --disable call the feature (id), whether it
 * is generated by default (tier), which features its code imports (requires),
 * the packages its generated code imports, and the frameworks and runtimes it
 * is generated for. The import-boundary lint
 * (.github/scripts/lint-import-boundaries.mjs) reads `requires` from this file:
 * features/<a>/ may import features/<b>/ only when the entry of a lists b.
 * Keep every entry on the lines it is written on below — the lint reads them
 * with a regular expression, not with a TypeScript parser.
 */

/**
 * stable: generated by default, removed with --disable.
 * experimental: backed by @maronn-openid-connect/experimental, whose API is
 *   not stable; generated only with --enable.
 * extension: pulls in an upstream identity provider through a package of its
 *   own; generated only with --enable.
 */
export type FeatureTier = 'stable' | 'experimental' | 'extension';

export type FrameworkName = 'hono' | 'express' | 'fastify' | 'nextjs';

/** Where the generated code of the feature runs. */
export type RuntimeName = 'node' | 'edge';

export interface FeatureEntry {
  /** The name of --enable / --disable, and of the directory under features/. */
  readonly id: string;
  readonly tier: FeatureTier;
  /** The features the code of this one imports; enabling it without them is an error. */
  readonly requires: readonly string[];
  /** The packages the generated code of the feature imports, beside @maronn-openid-connect/core. */
  readonly packages: readonly string[];
  readonly frameworks: readonly FrameworkName[];
  readonly runtimes: readonly RuntimeName[];
  /** One line for the help text. */
  readonly summary: string;
  /** Why the feature needs what it requires, for the error of a broken dependency. */
  readonly requiresReason?: string;
}

const ALL_FRAMEWORKS: readonly FrameworkName[] = ['hono', 'express', 'fastify', 'nextjs'];
const ALL_RUNTIMES: readonly RuntimeName[] = ['node', 'edge'];
const EXPERIMENTAL = ['@maronn-openid-connect/experimental'];

export const FEATURE_REGISTRY: readonly FeatureEntry[] = [
  { id: 'pkce', tier: 'stable', requires: [], packages: [], frameworks: ALL_FRAMEWORKS, runtimes: ALL_RUNTIMES, summary: 'PKCE (RFC 7636) required for every authorization code request' },
  { id: 'refresh-token', tier: 'stable', requires: [], packages: [], frameworks: ALL_FRAMEWORKS, runtimes: ALL_RUNTIMES, summary: 'refresh_token grant, offline_access and refresh token rotation' },
  { id: 'introspection', tier: 'stable', requires: [], packages: [], frameworks: ALL_FRAMEWORKS, runtimes: ALL_RUNTIMES, summary: 'Token Introspection endpoint (RFC 7662)' },
  { id: 'revocation', tier: 'stable', requires: [], packages: [], frameworks: ALL_FRAMEWORKS, runtimes: ALL_RUNTIMES, summary: 'Token Revocation endpoint (RFC 7009)' },
  { id: 'request-object', tier: 'stable', requires: [], packages: [], frameworks: ALL_FRAMEWORKS, runtimes: ALL_RUNTIMES, summary: 'signed Request Objects passed by value (OIDC Core 1.0 §6.1)' },
  { id: 'form-post-response-mode', tier: 'stable', requires: [], packages: [], frameworks: ALL_FRAMEWORKS, runtimes: ALL_RUNTIMES, summary: 'response_mode=form_post (OAuth 2.0 Form Post Response Mode)' },
  { id: 'implicit-flow', tier: 'stable', requires: [], packages: [], frameworks: ALL_FRAMEWORKS, runtimes: ALL_RUNTIMES, summary: 'Implicit Flow: response_type=id_token token / id_token (OIDC Core 1.0 §3.2)' },
  { id: 'par', tier: 'experimental', requires: [], packages: EXPERIMENTAL, frameworks: ALL_FRAMEWORKS, runtimes: ALL_RUNTIMES, summary: 'Pushed Authorization Requests (RFC 9126)' },
  { id: 'token-exchange', tier: 'experimental', requires: [], packages: EXPERIMENTAL, frameworks: ALL_FRAMEWORKS, runtimes: ALL_RUNTIMES, summary: 'OAuth 2.0 Token Exchange (RFC 8693)' },
  { id: 'jarm', tier: 'experimental', requires: [], packages: EXPERIMENTAL, frameworks: ALL_FRAMEWORKS, runtimes: ALL_RUNTIMES, summary: 'JWT Secured Authorization Response Mode (signed query.jwt)' },
  { id: 'device-authorization-grant', tier: 'experimental', requires: [], packages: EXPERIMENTAL, frameworks: ALL_FRAMEWORKS, runtimes: ALL_RUNTIMES, summary: 'OAuth 2.0 Device Authorization Grant (RFC 8628)' },
  { id: 'id-jag', tier: 'experimental', requires: [], packages: EXPERIMENTAL, frameworks: ALL_FRAMEWORKS, runtimes: ALL_RUNTIMES, summary: 'Identity Assertion Authorization Grant / Cross-App Access (ID-JAG)' },
  { id: 'ciba', tier: 'experimental', requires: [], packages: EXPERIMENTAL, frameworks: ALL_FRAMEWORKS, runtimes: ALL_RUNTIMES, summary: 'Client-Initiated Backchannel Authentication (CIBA Core 1.0, poll mode)' },
  { id: 'jwt-introspection-response', tier: 'experimental', requires: ['introspection'], packages: EXPERIMENTAL, frameworks: ALL_FRAMEWORKS, runtimes: ALL_RUNTIMES, summary: 'JWT Response for Token Introspection (RFC 9701)', requiresReason: 'the RFC 9701 JWT response is returned by the RFC 7662 introspection endpoint, which is not generated when introspection is disabled' },
  { id: 'rp-initiated-logout', tier: 'experimental', requires: [], packages: EXPERIMENTAL, frameworks: ALL_FRAMEWORKS, runtimes: ALL_RUNTIMES, summary: 'RP-Initiated Logout 1.0 (end_session_endpoint)' },
  { id: 'dynamic-client-registration', tier: 'experimental', requires: [], packages: EXPERIMENTAL, frameworks: ALL_FRAMEWORKS, runtimes: ALL_RUNTIMES, summary: 'Dynamic Client Registration (RFC 7591)' },
  { id: 'google-login', tier: 'extension', requires: [], packages: ['@maronn-openid-connect/google-login', 'google-auth-library'], frameworks: ALL_FRAMEWORKS, runtimes: ['node'], summary: 'Sign in with Google as a login method (Node.js 22+)' },
];

/** The entry of a feature id, or undefined for a name the CLI does not know. */
export function findFeature(id: string): FeatureEntry | undefined {
  return FEATURE_REGISTRY.find((entry) => entry.id === id);
}

/** The feature ids of a tier, in registry order. */
export function featureIdsOf(tier: FeatureTier): string[] {
  return FEATURE_REGISTRY.filter((entry) => entry.tier === tier).map((entry) => entry.id);
}

/** The OidcFeatureConfig key of a feature id: refresh-token → refreshToken. */
export function featureKeyOf(id: string): keyof OidcFeatureConfig {
  return id.replace(/-([a-z])/g, (_match, letter: string) => letter.toUpperCase()) as keyof OidcFeatureConfig;
}

/** The ids of the enabled features, in registry order (the order of features/enabled.ts). */
export function enabledFeatureIds(features: OidcFeatureConfig): string[] {
  return FEATURE_REGISTRY.filter((entry) => features[featureKeyOf(entry.id)]).map((entry) => entry.id);
}

// ---------------------------------------------------------------------------
// Feature toggles of a generation run

/**
 * Feature toggles for the generated OpenID Connect Provider.
 *
 * The default generation output enables every feature (the full Basic OP +
 * optional endpoints). Users can remove features from the default with
 * `--disable`, and explicitly (re-)enable them with `--enable`.
 *
 * Basic OP mandatory capabilities (authorize / token / userinfo / discovery /
 * jwks / login / consent) are not toggleable and are always generated. That
 * includes how the login / consent steps find their authorization transaction:
 * an HttpOnly transaction cookie set by /authorize, checked together with the
 * csrf_token embedded in the forms (the transaction id never appears in a URL).
 *
 * Experimental features live in the separate experimental package and their
 * APIs are unstable; extension features pull in an upstream identity provider.
 * Both must be requested explicitly with `--enable`.
 */

/** CLI-facing feature names (kebab-case, used with --enable / --disable). */
export const AVAILABLE_FEATURES = [
  'pkce',
  'refresh-token',
  'introspection',
  'revocation',
  'request-object',
  'form-post-response-mode',
  'implicit-flow',
] as const;

export type FeatureName = (typeof AVAILABLE_FEATURES)[number];

/**
 * Experimental feature names (kebab-case, used with --enable).
 *
 * Unlike AVAILABLE_FEATURES these are **disabled by default** and are only
 * generated when named explicitly with `--enable`. They are implemented in the
 * separate `@maronn-openid-connect/experimental` package, whose API is unstable and may
 * change in a breaking way between releases.
 *
 * - par: Pushed Authorization Requests (RFC 9126).
 * - token-exchange: OAuth 2.0 Token Exchange (RFC 8693), impersonation and
 *   delegation (act claim per §4.1).
 * - jarm: JWT Secured Authorization Response Mode (JARM), signed query.jwt only.
 * - device-authorization-grant: OAuth 2.0 Device Authorization Grant (RFC 8628).
 * - id-jag: Identity Assertion Authorization Grant / Cross-App Access
 *   (draft-ietf-oauth-identity-assertion-authz-grant-04) — issuing ID-JAGs via
 *   token exchange and redeeming them on the jwt-bearer grant.
 * - ciba: OpenID Connect Client-Initiated Backchannel Authentication (CIBA)
 *   Core 1.0, poll mode only — the client presents a login_hint over the back
 *   channel and polls the token endpoint while the user approves on their own
 *   browser.
 * - jwt-introspection-response: JWT Response for OAuth Token Introspection
 *   (RFC 9701) — the introspection endpoint answers a request whose Accept
 *   header names application/token-introspection+jwt with a signed JWT.
 *   Requires the introspection feature (its endpoint carries the response).
 * - rp-initiated-logout: OpenID Connect RP-Initiated Logout 1.0 — the OP serves
 *   the end_session_endpoint (GET|POST /logout) with a confirmation screen for
 *   requests without a valid id_token_hint, and redirects to a registered
 *   post_logout_redirect_uri on an exact match only.
 * - dynamic-client-registration: OAuth 2.0 Dynamic Client Registration
 *   (RFC 7591) — the OP serves the client registration endpoint
 *   (POST /register, open registration by default, optionally guarded by a
 *   single initial access token) and resolves the issued clients alongside the
 *   statically registered ones. Registration management (RFC 7592) is not
 *   implemented.
 */
export const EXPERIMENTAL_FEATURES = [
  'par',
  'token-exchange',
  'jarm',
  'device-authorization-grant',
  'id-jag',
  'ciba',
  'jwt-introspection-response',
  'rp-initiated-logout',
  'dynamic-client-registration',
] as const;

export type ExperimentalFeatureName = (typeof EXPERIMENTAL_FEATURES)[number];

/**
 * Extension feature names (kebab-case, used with --enable).
 *
 * Extensions live in their own package because they pull in something core
 * deliberately does not: an upstream identity provider and its official client
 * library. Like the experimental features they are **disabled by default** and
 * only generated when named explicitly with `--enable`.
 *
 * - google-login: Sign in with Google (Google Identity Services, redirect mode)
 *   as a login method next to the username / password form. The generated
 *   login page renders the Google button and a new login_uri endpoint
 *   (POST /login/google) verifies the posted ID token with Google's official
 *   google-auth-library through `@maronn-openid-connect/google-login`, then
 *   continues into the same session / consent steps as the password login.
 *   Node.js 22+ only: the Google library does not run on edge runtimes.
 */
export const EXTENSION_FEATURES = ['google-login'] as const;

export type ExtensionFeatureName = (typeof EXTENSION_FEATURES)[number];

/**
 * Resolved feature configuration passed through the generator pipeline.
 *
 * - pkce: when false, the generated config defaults to
 *   `allowNonPkceAuthorizationCodeFlow: true` (PKCE optional for explicit
 *   confidential clients; public clients still require it).
 * - refreshToken: when false, the token endpoint rejects the refresh_token
 *   grant with `unsupported_grant_type`, offline_access is never granted, and
 *   no refresh token is issued or persisted.
 * - introspection: when false, the RFC 7662 endpoint is not generated.
 * - revocation: when false, the RFC 7009 endpoint is not generated.
 * - requestObject: when false, the authorize endpoint rejects the `request`
 *   parameter with `request_not_supported` (OIDC Core 1.0 §6.3).
 * - formPostResponseMode: when true (the default), the authorization endpoint
 *   and the consent step answer a request with `response_mode=form_post` with
 *   an HTML form that posts the authorization response to the redirect URI
 *   (OAuth 2.0 Form Post Response Mode §2), and discovery advertises
 *   `form_post` in `response_modes_supported`. When false, `response_mode` is
 *   ignored as before and the response is the plain query one.
 * - implicitFlow: when true (the default), the authorization endpoint answers
 *   `response_type=id_token token` and `id_token` (OIDC Core 1.0 §3.2) for a
 *   client registered for them: the ID Token (and the access token) in the
 *   fragment of the redirect URI, without a code. Discovery advertises the
 *   two response types, `fragment` and the `implicit` grant type. When
 *   false, the authorization endpoint answers `response_type=code` only.
 * - par: experimental, disabled by default. When true, the PAR endpoint
 *   (RFC 9126) is generated and the authorization endpoint resolves URN-form
 *   `request_uri` values through `@maronn-openid-connect/experimental/par`.
 * - tokenExchange: experimental, disabled by default. When true, the token
 *   endpoint dispatches the `urn:ietf:params:oauth:grant-type:token-exchange`
 *   grant (RFC 8693) to `@maronn-openid-connect/experimental/token-exchange` before
 *   core's grant_type validation would reject the URN.
 * - jarm: experimental, disabled by default. When true, the authorization endpoint
 *   interprets `response_mode=query.jwt` (and its `jwt` shorthand) and returns
 *   the authorization response as a single signed JWT in the `response` query
 *   parameter, via `@maronn-openid-connect/experimental/jarm`. A request that
 *   does not ask for a JWT response mode is answered exactly as before.
 * - deviceAuthorizationGrant: experimental, disabled by default. When true, the
 *   OP additionally serves the device authorization endpoint
 *   (POST /device_authorization), the verification UI (/device, /device/login,
 *   /device/approve) and dispatches the
 *   `urn:ietf:params:oauth:grant-type:device_code` grant (RFC 8628) to
 *   `@maronn-openid-connect/experimental/device-authorization-grant` before
 *   core's grant_type validation would reject the URN.
 * - idJag: experimental, disabled by default. When true, the token endpoint issues
 *   ID-JAGs (Cross-App Access, draft-ietf-oauth-identity-assertion-authz-grant)
 *   on the token-exchange grant for
 *   `requested_token_type=urn:ietf:params:oauth:token-type:id-jag`, and redeems
 *   ID-JAGs from trusted identity providers on the
 *   `urn:ietf:params:oauth:grant-type:jwt-bearer` grant, both via
 *   `@maronn-openid-connect/experimental/id-jag` and both dispatched before
 *   core's grant_type validation would reject the URNs.
 * - ciba: experimental, disabled by default. When true, the OP additionally
 *   serves the backchannel authentication endpoint
 *   (POST /backchannel_authentication), the authentication device UI (/ciba,
 *   /ciba/login, /ciba/approve) and dispatches the
 *   `urn:openid:params:grant-type:ciba` grant (CIBA Core 1.0, poll mode) to
 *   `@maronn-openid-connect/experimental/ciba` before core's grant_type
 *   validation would reject the URN.
 * - jwtIntrospectionResponse: experimental, disabled by default. When true, the
 *   introspection endpoint answers a request whose Accept header names
 *   application/token-introspection+jwt with a signed introspection JWT
 *   (RFC 9701 §5, typ token-introspection+jwt, RS256) via
 *   `@maronn-openid-connect/experimental/jwt-introspection-response`, after
 *   restricting the disclosed members to the authenticated caller (§3). A
 *   request that does not name that media type is answered exactly as before.
 * - rpInitiatedLogout: experimental, disabled by default. When true, the OP
 *   additionally serves the end_session_endpoint (GET|POST /logout) and the
 *   confirmation approve endpoint (POST /logout/approve), advertises
 *   end_session_endpoint in discovery, and resolves the logout decision and the
 *   post_logout_redirect_uri (exact match against
 *   rpInitiatedLogoutConfig.postLogoutRedirectUris) via
 *   `@maronn-openid-connect/experimental/rp-initiated-logout`. Every other
 *   endpoint is generated exactly as before.
 * - dynamicClientRegistration: experimental, disabled by default. When true,
 *   the OP additionally serves the client registration endpoint
 *   (POST /register, RFC 7591), advertises registration_endpoint in discovery,
 *   validates the posted metadata and mints client_id / client_secret via
 *   `@maronn-openid-connect/experimental/dynamic-client-registration`, and
 *   resolves the registered clients from an in-memory store consulted after
 *   the configured client resolver. Every other endpoint is generated exactly
 *   as before.
 * - googleLogin: extension, disabled by default. When true, the login page
 *   renders a "Sign in with Google" button (redirect mode) and the OP serves
 *   POST /login/google, which verifies the ID token Google posts there with
 *   google-auth-library via `@maronn-openid-connect/google-login`, binds it to
 *   the authorization transaction through a single-use nonce, provisions the
 *   user just-in-time (a random subject, with the Google sub kept as its
 *   federated identity in db/) and hands off to consent like the password
 *   login. The button appears only once config.googleLogin is set.
 */
export interface OidcFeatureConfig {
  pkce: boolean;
  refreshToken: boolean;
  introspection: boolean;
  revocation: boolean;
  requestObject: boolean;
  formPostResponseMode: boolean;
  implicitFlow: boolean;
  par: boolean;
  tokenExchange: boolean;
  jarm: boolean;
  deviceAuthorizationGrant: boolean;
  idJag: boolean;
  ciba: boolean;
  jwtIntrospectionResponse: boolean;
  rpInitiatedLogout: boolean;
  dynamicClientRegistration: boolean;
  googleLogin: boolean;
}

/** Mapping from CLI feature names to OidcFeatureConfig keys. */
const FEATURE_KEYS: Record<FeatureName, keyof OidcFeatureConfig> = {
  pkce: 'pkce',
  'refresh-token': 'refreshToken',
  introspection: 'introspection',
  revocation: 'revocation',
  'request-object': 'requestObject',
  'form-post-response-mode': 'formPostResponseMode',
  'implicit-flow': 'implicitFlow',
};

/** Mapping from CLI experimental feature names to OidcFeatureConfig keys. */
const EXPERIMENTAL_FEATURE_KEYS: Record<ExperimentalFeatureName, keyof OidcFeatureConfig> = {
  par: 'par',
  'token-exchange': 'tokenExchange',
  jarm: 'jarm',
  'device-authorization-grant': 'deviceAuthorizationGrant',
  'id-jag': 'idJag',
  ciba: 'ciba',
  'jwt-introspection-response': 'jwtIntrospectionResponse',
  'rp-initiated-logout': 'rpInitiatedLogout',
  'dynamic-client-registration': 'dynamicClientRegistration',
};

/** Mapping from CLI extension feature names to OidcFeatureConfig keys. */
const EXTENSION_FEATURE_KEYS: Record<ExtensionFeatureName, keyof OidcFeatureConfig> = {
  'google-login': 'googleLogin',
};

/**
 * Default: every stable feature enabled (matches the historical generation
 * output), every experimental and extension feature disabled.
 */
export const DEFAULT_FEATURES: OidcFeatureConfig = {
  pkce: true,
  refreshToken: true,
  introspection: true,
  revocation: true,
  requestObject: true,
  formPostResponseMode: true,
  implicitFlow: true,
  par: false,
  tokenExchange: false,
  jarm: false,
  deviceAuthorizationGrant: false,
  idJag: false,
  ciba: false,
  jwtIntrospectionResponse: false,
  rpInitiatedLogout: false,
  dynamicClientRegistration: false,
  googleLogin: false,
};

function isExperimentalFeature(name: string): name is ExperimentalFeatureName {
  return (EXPERIMENTAL_FEATURES as readonly string[]).includes(name);
}

function isExtensionFeature(name: string): name is ExtensionFeatureName {
  return (EXTENSION_FEATURES as readonly string[]).includes(name);
}

function assertKnownFeature(
  name: string,
): asserts name is FeatureName | ExperimentalFeatureName | ExtensionFeatureName {
  if (
    !(AVAILABLE_FEATURES as readonly string[]).includes(name) &&
    !isExperimentalFeature(name) &&
    !isExtensionFeature(name)
  ) {
    throw new Error(
      `Unknown feature: "${name}". Available features: ${AVAILABLE_FEATURES.join(', ')}. ` +
        `Experimental features (disabled by default): ${EXPERIMENTAL_FEATURES.join(', ')}. ` +
        `Extension features (disabled by default): ${EXTENSION_FEATURES.join(', ')}`,
    );
  }
}

function featureKey(
  name: FeatureName | ExperimentalFeatureName | ExtensionFeatureName,
): keyof OidcFeatureConfig {
  if (isExtensionFeature(name)) return EXTENSION_FEATURE_KEYS[name];
  return isExperimentalFeature(name) ? EXPERIMENTAL_FEATURE_KEYS[name] : FEATURE_KEYS[name];
}

/**
 * Resolve CLI --enable / --disable lists into an OidcFeatureConfig,
 * starting from DEFAULT_FEATURES.
 *
 * @throws {Error} on an unknown feature name, or a feature listed in both
 *   enable and disable.
 */
export function resolveFeatures(options: {
  enable?: string[];
  disable?: string[];
}): OidcFeatureConfig {
  const enable = options.enable ?? [];
  const disable = options.disable ?? [];

  for (const name of [...enable, ...disable]) {
    assertKnownFeature(name);
  }

  for (const name of enable) {
    if (disable.includes(name)) {
      throw new Error(`Feature "${name}" cannot be both enabled and disabled`);
    }
  }

  const features: OidcFeatureConfig = { ...DEFAULT_FEATURES };
  for (const name of enable) {
    assertKnownFeature(name);
    features[featureKey(name)] = true;
  }
  // An experimental / extension feature listed in --disable is
  // already off by default, so this is a no-op rather than an error (same as
  // omitting it).
  for (const name of disable) {
    assertKnownFeature(name);
    features[featureKey(name)] = false;
  }
  assertFeatureDependencies(features);
  return features;
}

/**
 * Cross-feature dependencies: a feature whose code imports another one
 * (requires in the registry) cannot be generated without it.
 *
 * @throws {Error} when a feature is enabled without a feature it requires.
 */
export function assertFeatureDependencies(features: OidcFeatureConfig): void {
  for (const entry of FEATURE_REGISTRY) {
    if (!features[featureKeyOf(entry.id)]) continue;
    for (const required of entry.requires) {
      if (features[featureKeyOf(required)]) continue;
      throw new Error(
        `Feature "${entry.id}" requires the ${required} feature` +
          (entry.requiresReason === undefined ? '' : `: ${entry.requiresReason}`),
      );
    }
  }
}

/** The OidcFeatureConfig keys, in declaration order (also the manifest order). */
export const FEATURE_CONFIG_KEYS = Object.keys(DEFAULT_FEATURES) as (keyof OidcFeatureConfig)[];

/**
 * Turn a feature object read from a file (a flow document, a manifest) into an
 * OidcFeatureConfig: every key must be a known feature with a boolean value;
 * a key that is left out keeps its default.
 *
 * @throws {Error} on an unknown key, a non-boolean value, or a broken dependency.
 */
export function normalizeFeatures(input: unknown, source = 'features'): OidcFeatureConfig {
  if (typeof input !== 'object' || input === null || Array.isArray(input)) {
    throw new Error(`${source} must be an object of feature flags`);
  }
  const features: OidcFeatureConfig = { ...DEFAULT_FEATURES };
  for (const [key, value] of Object.entries(input)) {
    if (!(FEATURE_CONFIG_KEYS as string[]).includes(key)) {
      throw new Error(
        `${source} has an unknown feature "${key}". Known features: ${FEATURE_CONFIG_KEYS.join(', ')}`,
      );
    }
    if (typeof value !== 'boolean') {
      throw new Error(`${source}.${key} must be true or false`);
    }
    features[key as keyof OidcFeatureConfig] = value;
  }
  assertFeatureDependencies(features);
  return features;
}
